import pandas as pd
from typing import Dict

def run(inputs: Dict[str, pd.DataFrame]) -> Dict[str, pd.DataFrame]:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # Ensure target_state has the right structure
    if target_state.empty:
        target_state = pd.DataFrame(columns=['order_id', 'status', 'amount', 'last_seq'])

    # Initialize output state as a copy of target
    new_state_dict = {}
    for _, row in target_state.iterrows():
        order_id = row['order_id']
        new_state_dict[order_id] = {
            'status': row['status'],
            'amount': row['amount'],
            'last_seq': row['last_seq']
        }

    # Track which orders have been touched and their last operation
    tombstone_dict = {}  # order_id -> (deleted_seq) if last op is 'D'

    # Sort events by seq (and order_id for determinism, though seq should be globally unique)
    cdc_events = cdc_events.sort_values(by=['seq', 'order_id']).reset_index(drop=True)

    # Remove duplicates by seq, keeping the first occurrence (they should be identical)
    cdc_events = cdc_events.drop_duplicates(subset=['seq'], keep='first').reset_index(drop=True)

    # Process events in seq order
    for _, event in cdc_events.iterrows():
        seq = event['seq']
        order_id = event['order_id']
        op = event['op']
        status = event['status']
        amount = event['amount']

        # Replay guard: skip if order exists in target_state and seq <= last_seq
        if order_id in new_state_dict:
            if seq <= new_state_dict[order_id]['last_seq']:
                continue

        # Apply the event
        if op in ('I', 'U'):
            if order_id not in new_state_dict:
                # Create new row
                new_state_dict[order_id] = {
                    'status': status,
                    'amount': amount,
                    'last_seq': seq
                }
                tombstone_dict.pop(order_id, None)  # Clear tombstone if was deleted before
            else:
                # Update existing row
                new_state_dict[order_id]['status'] = status
                # For 'U' with NULL amount, keep existing amount
                if op == 'U' and pd.isna(amount):
                    # Keep existing amount
                    pass
                else:
                    new_state_dict[order_id]['amount'] = amount
                new_state_dict[order_id]['last_seq'] = seq
                tombstone_dict.pop(order_id, None)  # Clear tombstone if was deleted before
        elif op == 'D':
            if order_id in new_state_dict:
                # Mark as tombstone
                tombstone_dict[order_id] = seq
                del new_state_dict[order_id]

    # Build new_state DataFrame
    new_state_rows = []
    for order_id, state in sorted(new_state_dict.items()):
        new_state_rows.append({
            'order_id': order_id,
            'status': state['status'],
            'amount': state['amount'],
            'last_seq': state['last_seq']
        })

    if new_state_rows:
        new_state_df = pd.DataFrame(new_state_rows)
    else:
        new_state_df = pd.DataFrame(columns=['order_id', 'status', 'amount', 'last_seq'])

    # Ensure correct dtypes for new_state
    new_state_df = new_state_df.astype({
        'order_id': 'int64',
        'status': 'object',
        'amount': 'float64',
        'last_seq': 'int64'
    })

    # Build tombstones DataFrame
    tombstone_rows = []
    for order_id in sorted(tombstone_dict.keys()):
        tombstone_rows.append({
            'order_id': order_id,
            'deleted_seq': tombstone_dict[order_id]
        })

    if tombstone_rows:
        tombstones_df = pd.DataFrame(tombstone_rows)
    else:
        tombstones_df = pd.DataFrame(columns=['order_id', 'deleted_seq'])

    # Ensure correct dtypes for tombstones
    tombstones_df = tombstones_df.astype({
        'order_id': 'int64',
        'deleted_seq': 'int64'
    })

    return {
        'new_state': new_state_df,
        'tombstones': tombstones_df
    }
